exercise.answer:
// lesson01 ch01 解答
package main

import "fmt"

func main() {
	// Println は出力の最後に自動で改行を付けるため、
	// 「1行ずつ出力」は Println を行の数だけ並べるのが最も素直です。
	fmt.Println("Hello, Go!")
	fmt.Println("研修から来ました")
}
